<script setup>
import {computed,reactive,ref} from 'vue';
const props=defineProps({mode:String,indexUrl:String,storeUrl:String,updateUrl:String,csrf:String,payload:String,errors:String,old:String});
function parse(value){try{return JSON.parse(value||'{}')}catch{return {}}}
const payload=parse(props.payload), errors=parse(props.errors), old=parse(props.old), user=payload.user||{};
const form=reactive({first_name:old.first_name??user.first_name??'',last_name:old.last_name??user.last_name??'',username:old.username??user.username??'',email:old.email??user.email??'',phone:old.phone??user.phone??'',role:old.role??payload.role_name??'',status:old.status??user.status??'active'});
const action=computed(()=>props.mode==='create'?props.storeUrl:props.updateUrl),photo=ref(null),preview=ref(payload.photo_url||'');
function previewPhoto(e){const file=e.target.files?.[0];if(file){photo.value=file;preview.value=URL.createObjectURL(file)}}
</script>
<template>
<div class="dashboard-section users-page"><div class="users-edit-hero mb-4"><div class="users-edit-hero-content"><div class="users-edit-breadcrumb"><a :href="indexUrl"><i class="bi bi-people"></i> Users</a><i class="bi bi-chevron-right"></i><span>{{mode==='create'?'Add User':'Edit User'}}</span></div><span class="hero-badge"><i class="bi bi-person-vcard"></i> Account Management</span><h1>{{mode==='create'?'Add user':'Edit user'}}</h1><p>Manage account details, access and profile information.</p></div><div class="users-edit-hero-mark"><i class="bi bi-person-vcard"></i></div></div>
<div class="dashboard-panel p-4"><div v-if="Object.keys(errors).length" class="alert alert-danger"><strong>Please fix the following errors.</strong><ul class="mb-0"><li v-for="(messages,key) in errors" :key="key">{{messages[0]}}</li></ul></div><form :action="action" method="POST" enctype="multipart/form-data"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT"><div class="row g-3"><div class="col-md-6"><label class="form-label">First name <span class="text-danger">*</span></label><input v-model="form.first_name" name="first_name" class="form-control" required maxlength="100"><small v-if="errors.first_name" class="text-danger">{{errors.first_name[0]}}</small></div><div class="col-md-6"><label class="form-label">Last name <span class="text-danger">*</span></label><input v-model="form.last_name" name="last_name" class="form-control" required maxlength="100"><small v-if="errors.last_name" class="text-danger">{{errors.last_name[0]}}</small></div><div class="col-md-6"><label class="form-label">Username <span class="text-danger">*</span></label><input v-model="form.username" name="username" class="form-control" required maxlength="100"><small v-if="errors.username" class="text-danger">{{errors.username[0]}}</small></div><div class="col-md-6"><label class="form-label">Email <span class="text-danger">*</span></label><input v-model="form.email" name="email" type="email" class="form-control" required maxlength="255"><small v-if="errors.email" class="text-danger">{{errors.email[0]}}</small></div><div class="col-md-6"><label class="form-label">Phone</label><input v-model="form.phone" name="phone" class="form-control" maxlength="30"></div><div class="col-md-6"><label class="form-label">Profile photo</label><input name="profile_photo" type="file" accept="image/jpeg,image/png,image/webp" class="form-control" @change="previewPhoto"><img v-if="preview" :src="preview" alt="Profile preview" class="mt-2 rounded" style="max-width:96px;max-height:96px;object-fit:cover"></div><div class="col-md-6"><label class="form-label">Role <span class="text-danger">*</span></label><input v-if="payload.is_current" type="hidden" name="role" :value="form.role"><select v-model="form.role" name="role" class="form-select" required :disabled="payload.is_current"><option value="">Select role</option><option v-for="role in payload.roles||[]" :key="role.name" :value="role.name">{{role.display_name}}</option></select><small v-if="errors.role" class="text-danger">{{errors.role[0]}}</small></div><div class="col-md-6"><label class="form-label">Status <span class="text-danger">*</span></label><input v-if="payload.is_current" type="hidden" name="status" :value="form.status"><select v-model="form.status" name="status" class="form-select" required :disabled="payload.is_current"><option v-for="status in ['active','inactive','banned']" :key="status">{{status}}</option></select></div><div class="col-md-6"><label class="form-label">{{mode==='create'?'Password':'New password'}}</label><input name="password" type="password" class="form-control" :required="mode==='create'" minlength="8" autocomplete="new-password"><small v-if="errors.password" class="text-danger">{{errors.password[0]}}</small></div><div class="col-md-6"><label class="form-label">Confirm password</label><input name="password_confirmation" type="password" class="form-control" :required="mode==='create'" minlength="8" autocomplete="new-password"></div></div><div class="d-flex justify-content-end gap-2 mt-4"><a :href="indexUrl" class="btn btn-light">Cancel</a><button class="btn btn-primary" type="submit">{{mode==='create'?'Create user':'Save changes'}}</button></div></form></div></div>
</template>
